document.querySelector(".achieved").addEventListener("click", function() {
    let currentState = this.dataset.state;

    // 切換 data-state
    this.dataset.state = currentState === "closed" ? "open" : "closed";
});

P
document.querySelectorAll('.achieved').forEach(button =&gt; {
    button.addEventListener('click', function() {
        const content = this.nextElementSibling;
        if (content.style.height) {
            content.style.height = null;
            content.classList.remove('open');
        } else {
            document.querySelectorAll('.collapse').forEach(c =&gt; {
                c.style.height = null;
                c.classList.remove('open');
            });
            content.style.height = content.scrollHeight + 'px';
            content.classList.add('open');
        }
    });
});
